def regex(self, protocols, localhost=True):
    p = '^'
    p += '(?:(?:(?:{}):)?//)'.format('|'.join(protocols))
    p += '(?:\\S+(?::\\S*)?@)?'
    p += '(?:'
    p += '(?!(?:10|127)(?:\\.\\d{1,3}){3})'
    p += '(?!(?:169\\.254|192\\.168)(?:\\.\\d{1,3}){2})'
    p += '(?!172\\.(?:1[6-9]|2\\d|3[0-1])(?:\\.\\d{1,3}){2})'
    p += '(?:[1-9]\\d?|1\\d\\d|2[01]\\d|22[0-3])'
    p += '(?:\\.(?:1?\\d{1,2}|2[0-4]\\d|25[0-5])){2}'
    p += '(?:\\.(?:[1-9]\\d?|1\\d\\d|2[0-4]\\d|25[0-4]))'
    p += '|'
    p += '(?:'
    p += '(?:'
    p += '[a-z0-9\\u00a1-\\uffff][a-z0-9\\u00a1-\\uffff_-]{0,62})?'
    p += '[a-z0-9\\u00a1-\\uffff]'
    p += '\\.' if not localhost else '[\\.]?|localhost'
    p += ')+'
    p += '(?:[a-z\\u00a1-\\uffff]{2,}\\.?)'
    p += ')'
    p += '(?::\\d{2,5})?'
    p += '(?:[/?#]\\S*)?'
    p += '$'
    return p